};

// 1. DECLARE INPUTS
const workoutHistory = $("get_workout_exercise").all();
const workoutTypes = $("get_workout_types").all();
const workoutData = $("split_out_exercise").all();
const mergedItems = $("merge_new_exerciseid").all();

// 2. CALCULATE NEXT WORKOUT ID (Max + 1)
const existingIds = workoutHistory
  .map(item => Number(item.json.workout_id))
  .filter(id => Number.isFinite(id));
const nextWorkoutId = (existingIds.length > 0 ? Math.max(...existingIds) : 0) + 1;

// 3. MAP EVERYTHING TOGETHER
return mergedItems.map((item) => {
  // JOIN: Find original metadata using the validated key 'exercise_name'
  // We use .trim().toLowerCase() to ensure a 100% match success rate
  const match = workoutData.find(d => 
    d.json.exercise_name?.toLowerCase().trim() === item.json.exercise_name_normalized?.toLowerCase().trim()
  );

  const original = match ? match.json : {};

  // LOOKUP: Resolve workout_type_id from your reference table
  const typeMatch = workoutTypes.find(t => 
    t.json.workout_type_name?.toLowerCase().trim() === original.workout_type_name?.toLowerCase().trim()
  );
  const actualTypeId = typeMatch ? typeMatch.json.workout_type_id : null;

  return {
    json: {
      ...item.json,                  // Keep: exercise_id, row_number, is_new, name_normalized
      workout_id: nextWorkoutId,     // Add: The incremented session ID
      workout_date: original.workout_date,
      workout_type_id: actualTypeId, // Resolved from the reference sheet
      workout_rounds: original.rounds,
      workout_repetition_type: original.repetition_type,
      workout_repetition_amount: original.repetition_amount
    }
  };
});

