// ── PARSE AGENT INTENT ───────────────────────────────────────────
const agentRaw = $('ai_agent_prompt_process').first().json.output;
const agentOutput = JSON.parse(agentRaw);

const focusRaw = (agentOutput.body_part_focus || 'full body').toLowerCase().trim();
const volumeMode = (agentOutput.volume_logic || 'same').toLowerCase();
const isProgressive = volumeMode === 'progressive';
const workoutSize = parseInt(agentOutput.workout_size) || 5;

// ── CATALOG & HISTORY ────────────────────────────────────────────
const catalog = $('get_exercise_catalog').all();
const history = $('get_recent_workouts').all();

// ── FILTER by body part ──────────────────────────────────────────
let pool = catalog.filter(function(ex) {
  const bp = (ex.json.exercise_body_part_focus || '').toLowerCase();
  if (focusRaw === 'full body') return true;
  return bp.includes(focusRaw) || focusRaw.includes(bp);
});

if (pool.length === 0) pool = catalog;

// ── SORT by frequency ascending (least used first) ───────────────
pool.sort(function(a, b) {
  const fa = Number(a.json.exercise_frequency) || 0;
  const fb = Number(b.json.exercise_frequency) || 0;
  return fa - fb;
});

// ── 80/20 SPLIT ──────────────────────────────────────────────────
const lowCount = Math.max(1, Math.round(workoutSize * 0.2));
const highCount = workoutSize - lowCount;

const lowFreqSize = Math.ceil(pool.length * 0.3);
const highFreqSize = Math.ceil(pool.length * 0.7);
const lowFreqPool = pool.slice(0, lowFreqSize);
const highFreqPool = pool.slice(pool.length - highFreqSize);

function pickRandom(arr, n) {
  const shuffled = arr.slice().sort(function() { return Math.random() - 0.5; });
  return shuffled.slice(0, Math.min(n, shuffled.length));
}

const selected = pickRandom(highFreqPool, highCount).concat(pickRandom(lowFreqPool, lowCount));

// ── MOVEMENT PATTERN ROTATION ────────────────────────────────────
const patternOrder = ['squat', 'hinge', 'push', 'pull', 'rotation', 'carry'];
selected.sort(function(a, b) {
  const pa = patternOrder.indexOf((a.json.exercise_movement_pattern || '').toLowerCase());
  const pb = patternOrder.indexOf((b.json.exercise_movement_pattern || '').toLowerCase());
  return (pa === -1 ? 99 : pa) - (pb === -1 ? 99 : pb);
});

// ── LOOK UP LAST USED REPS/ROUNDS ────────────────────────────────
function getLastEntry(exerciseName) {
  const matches = history.filter(function(h) {
    return (h.json.workout_exercise_name || '').toLowerCase().trim() ===
           (exerciseName || '').toLowerCase().trim();
  });
  matches.sort(function(a, b) {
    return (b.json.workout_date || '').localeCompare(a.json.workout_date || '');
  });
  return matches.length > 0 ? matches[0].json : null;
}

// ── BUILD OUTPUT ─────────────────────────────────────────────────
const result = selected.map(function(ex) {
  const last = getLastEntry(ex.json.exercise_name);
  let baseReps = last ? (last.workout_repetition_amount || 10) : 10;
  let baseRounds = last ? Number(last.workout_rounds) || 3 : 3;
  let repType = last ? (last.workout_repetition_type || 'reps') : 'reps';

  if (isProgressive) {
    if (repType === 'time') {
      // Parse the time string e.g. "30 sec", "1 min", "90sec"
      const timeStr = String(baseReps).toLowerCase().trim();
      const timeNum = parseFloat(timeStr);
      const isMin = timeStr.includes('min');
      const isSec = timeStr.includes('sec');
      if (!isNaN(timeNum)) {
        const increased = Math.ceil(timeNum * 1.1);
        if (isMin) {
          baseReps = increased + ' min';
        } else if (isSec) {
          baseReps = increased + ' sec';
        } else {
          baseReps = increased + ' sec'; // fallback assume seconds
        }
      }
    } else {
      // Numeric reps — apply +10%
      baseReps = Math.ceil(Number(baseReps) * 1.1);
    }
  }

  return {
    exercise_name: ex.json.exercise_name,
    body_part: ex.json.exercise_body_part_focus,
    movement_pattern: ex.json.exercise_movement_pattern,
    equipment: ex.json.exercise_primary_equipment,
    repetition_type: repType,
    repetition_amount: baseReps,
    rounds: baseRounds,
    is_new_exercise: (Number(ex.json.exercise_frequency) || 0) === 0
  };
});

return [{ json: {
  body_part_focus: focusRaw,
  volume_mode: volumeMode,
  exercises: result
}}];

// READ SOURCE DATA - use $input first, fall back to node references
var exercises = [];
var focus = 'full body';
var mode = 'same';

var inputData = $input.first().json;

if (inputData && inputData.exercises && inputData.exercises.length > 0) {
  exercises = inputData.exercises;
  focus = inputData.body_part_focus || 'full body';
  mode = inputData.volume_mode || 'same';
} else {
  try {
    var genData = $('code_workout_generator').first().json;
    if (genData && genData.exercises && genData.exercises.length > 0) {
      exercises = genData.exercises;
      focus = genData.body_part_focus || 'full body';
      mode = genData.volume_mode || 'same';
    }
  } catch(e) {}

  if (exercises.length === 0) {
    try {
      var modData = $('code_handle_modify').first().json;
      if (modData && modData.exercises && modData.exercises.length > 0) {
        exercises = modData.exercises;
        focus = modData.body_part_focus || 'full body';
        mode = modData.volume_mode || 'same';
      }
    } catch(e) {}
  }
}

// ── HEADER ───────────────────────────────────────────────────────
const patterns = [];
const equipment = [];
for (let i = 0; i < exercises.length; i++) {
  const e = exercises[i];
  if (e.movement_pattern && patterns.indexOf(e.movement_pattern) === -1) {
    patterns.push(e.movement_pattern);
  }
  if (e.equipment && equipment.indexOf(e.equipment) === -1) {
    equipment.push(e.equipment);
  }
}

const focusLabel = focus.charAt(0).toUpperCase() + focus.slice(1);
const volumeLabel = mode === 'progressive' ? '+10% progressive' : 'Same as last';

const header = '**Workout Focus:** ' + focusLabel +
  ' | **Patterns:** ' + patterns.join(', ') +
  ' | **Volume:** ' + volumeLabel + '\n' +
  '**Equipment needed:** ' + equipment.join(', ') + '\n\n';

// ── TABLE ────────────────────────────────────────────────────────
const tableHeader = '| # | Exercise | Rep Type | Amount | Rounds |';
const tableDivider = '|---|----------|----------|--------|--------|';

const tableRows = [];
for (let i = 0; i < exercises.length; i++) {
  const ex = exercises[i];
  const newTag = ex.is_new_exercise ? ' 🆕' : '';
  tableRows.push('| ' + (i + 1) + ' | ' + ex.exercise_name + newTag +
    ' | ' + ex.repetition_type +
    ' | ' + ex.repetition_amount +
    ' | ' + ex.rounds + ' |');
}

const table = [tableHeader, tableDivider].concat(tableRows).join('\n');

// ── FOOTER ───────────────────────────────────────────────────────
const footer = '\n\n---\nReply with:\n' +
  '• **Confirm** — save this workout\n' +
  '• **Replace [exercise name] with [new exercise]** — swap an exercise\n' +
  '• **Add [exercise name]** — add a specific exercise\n' +
  '• **Remove #N or [exercise name]** — remove an exercise\n' +
  '• **Regenerate** — create a completely new suggestion';

const fullMessage = header + table + footer;

return [{ json: {
  suggestion_text: fullMessage,
  exercises_json: JSON.stringify(exercises),
  body_part_focus: focus,
  volume_mode: mode
}}];

