var agentRaw = $('ai_agent_prompt_process').first().json.output;
var agentOutput = JSON.parse(agentRaw);
var action = agentOutput.action;
var catalog = $('get_exercise_catalog_modify').all();
var history = $('get_recent_workouts_modify').all();
var currentExercises = [];
try {
  var stagedRaw = $('get_staged_workout').first().json.exercises_json;
  if (stagedRaw && stagedRaw !== 'undefined') {
    currentExercises = JSON.parse(stagedRaw);
  }
} catch(e) {
  currentExercises = [];
}

function findInCatalog(name) {
  var nameLower = name.toLowerCase().trim();
  // Also try with 's' added or removed for plural/singular matching
  var namePlural = nameLower.endsWith('s') ? nameLower : nameLower + 's';
  var nameSingular = nameLower.endsWith('s') ? nameLower.slice(0, -1) : nameLower;

  for (var i = 0; i < catalog.length; i++) {
    var cat = catalog[i].json;
    var catName = (cat.exercise_name || '').toLowerCase().trim();
    var catNorm = (cat.exercise_name_normalized || '').toLowerCase().trim();

    if (catName === nameLower || catNorm === nameLower ||
        catName === namePlural || catName === nameSingular ||
        catNorm === namePlural || catNorm === nameSingular) {
      return cat;
    }
  }
  return null;
}

function findInHistory(name) {
  var nameLower = name.toLowerCase().trim();
  var namePlural = nameLower.endsWith('s') ? nameLower : nameLower + 's';
  var nameSingular = nameLower.endsWith('s') ? nameLower.slice(0, -1) : nameLower;
  var best = null;
  for (var i = 0; i < history.length; i++) {
    var h = history[i].json;
    var hName = (h.workout_exercise_name || '').toLowerCase().trim();
    if (hName === nameLower || hName === namePlural || hName === nameSingular) {
      if (!best || (h.workout_date || '') > (best.workout_date || '')) {
        best = h;
      }
    }
  }
  return best;
}

function buildExercise(catEntry, histEntry) {
  var repType = 'reps';
  if (histEntry && histEntry.workout_repetition_type) {
    repType = histEntry.workout_repetition_type;
  }
  var repAmount = 10;
  if (histEntry && histEntry.workout_repetition_amount) {
    repAmount = histEntry.workout_repetition_amount;
  }
  var rounds = 3;
  if (histEntry && histEntry.workout_rounds) {
    rounds = Number(histEntry.workout_rounds);
  }
  var ex = {};
  ex.exercise_name = catEntry.exercise_name;
  ex.body_part = catEntry.exercise_body_part_focus;
  ex.movement_pattern = catEntry.exercise_movement_pattern;
  ex.equipment = catEntry.exercise_primary_equipment;
  ex.repetition_type = repType;
  ex.repetition_amount = repAmount;
  ex.rounds = rounds;
  ex.is_new_exercise = (Number(catEntry.exercise_frequency) || 0) === 0;
  return ex;
}

function makeResult(exercises) {
  var r = {};
  r.body_part_focus = 'full body';
  r.volume_mode = 'same';
  r.exercises = exercises;
  return r;
}

if (action === 'regenerate') {
  var newFocus = agentOutput.body_part_focus || 'full body';
  var newVolume = agentOutput.volume_logic || 'same';
  var newSize = parseInt(agentOutput.workout_size) || 5;
  var regenData = {};
  regenData.intent = 'generate';
  regenData.body_part_focus = newFocus;
  regenData.volume_logic = newVolume;
  regenData.workout_size = newSize;
  regenData.output = JSON.stringify(regenData);
  return [{ json: regenData }];
}

if (action === 'replace') {
  var exName = (agentOutput.exercise_name || '').toLowerCase().trim();
  var newExName = (agentOutput.new_exercise_name || '').toLowerCase().trim();
  var exIndex = agentOutput.exercise_index;

  var targetIdx = -1;
  if (exIndex !== null && exIndex !== undefined) {
    targetIdx = exIndex - 1;
  } else {
    for (var i = 0; i < currentExercises.length; i++) {
      if ((currentExercises[i].exercise_name || '').toLowerCase().trim() === exName) {
        targetIdx = i;
        break;
      }
    }
  }

  var repCat = findInCatalog(newExName);

  if (targetIdx === -1) {
    var e1 = makeResult(currentExercises);
    e1.error_message = 'Exercise not found: ' + exName;
    return [{ json: e1 }];
  }

  if (!repCat) {
    var e2 = makeResult(currentExercises);
    e2.error_message = 'Replacement not found: ' + newExName;
    return [{ json: e2 }];
  }

  var repHist = findInHistory(newExName);
  var newExObj = buildExercise(repCat, repHist);

  var replacedList = [];
  for (var j = 0; j < currentExercises.length; j++) {
    if (j === targetIdx) {
      replacedList.push(newExObj);
    } else {
      replacedList.push(currentExercises[j]);
    }
  }
  return [{ json: makeResult(replacedList) }];
}

if (action === 'add') {
  var addExName = (agentOutput.new_exercise_name || '').toLowerCase().trim();
  var addCat = findInCatalog(addExName);

  if (!addCat) {
    var addErr = makeResult(currentExercises);
    addErr.needs_new_exercise = true;
    addErr.new_exercise_name = agentOutput.new_exercise_name;
    return [{ json: addErr }];
  }

  var addHist = findInHistory(addExName);
  var addExObj = buildExercise(addCat, addHist);
  var addedList = currentExercises.slice();
  addedList.push(addExObj);
  return [{ json: makeResult(addedList) }];
}

if (action === 'remove') {
  var remName = (agentOutput.exercise_name || '').toLowerCase().trim();
  var remIndex = agentOutput.exercise_index;
  var remTarget = -1;

  if (remIndex !== null && remIndex !== undefined) {
    remTarget = remIndex - 1;
  } else {
    for (var k = 0; k < currentExercises.length; k++) {
      if ((currentExercises[k].exercise_name || '').toLowerCase().trim() === remName) {
        remTarget = k;
        break;
      }
    }
  }

  var removedList = [];
  for (var l = 0; l < currentExercises.length; l++) {
    if (l !== remTarget) {
      removedList.push(currentExercises[l]);
    }
  }
  return [{ json: makeResult(removedList) }];
}

var fallback = makeResult(currentExercises);
fallback.error_message = 'Unknown action: ' + action;
return [{ json: fallback }];

var stagedRaw = $('get_staged_workout_confirm').first().json.exercises_json;
var exercises = [];

try {
  if (stagedRaw) {
    var jsonStart = stagedRaw.indexOf('[');
    if (jsonStart >= 0) {
      stagedRaw = stagedRaw.substring(jsonStart);
    }
    exercises = JSON.parse(stagedRaw);
  }
} catch(e) {
  exercises = [];
}

var today = new Date().toISOString().split('T')[0];

var result = {};
result.intent = 'log';
result.workout_date = today;
result.workout_type_name = 'full body';
result.exercises = exercises.map(function(ex) {
  var mapped = {};
  mapped.exercise_name = ex.exercise_name;
  mapped.rounds = ex.rounds;
  mapped.repetition_type = ex.repetition_type;
  mapped.repetition_amount = ex.repetition_amount;
  mapped.workout_type_name = 'full body';
  mapped.workout_date = today;
  return mapped;
});

return [{ json: result }];
